CREATE TABLE IF NOT EXISTS gis_provider_retrieval_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dataset_id uuid NOT NULL REFERENCES gis_provider_datasets(id) ON DELETE CASCADE, retrieval_url text NOT NULL, http_status integer, content_type text, payload_bytes integer, payload_hash text, retrieval_status text NOT NULL DEFAULT 'Started', feature_count integer NOT NULL DEFAULT 0, error_message text, retrieved_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_provider_retrieval_features (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), retrieval_run_id uuid NOT NULL REFERENCES gis_provider_retrieval_runs(id) ON DELETE CASCADE, source_feature_id text, area_code text, parent_area_code text, area_name text, parent_area_name text, geometry_type text, geometry_json jsonb NOT NULL, feature_hash text NOT NULL, geometry_qa_status text NOT NULL DEFAULT 'Pending', code_qa_status text NOT NULL DEFAULT 'Pending', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_gis_retrieval_runs_dataset ON gis_provider_retrieval_runs(dataset_id,retrieved_at DESC);
CREATE INDEX IF NOT EXISTS idx_gis_retrieval_features_run ON gis_provider_retrieval_features(retrieval_run_id,area_code);
ALTER TABLE gis_provider_datasets ADD COLUMN IF NOT EXISTS payload_endpoint_url text;
ALTER TABLE gis_provider_datasets ADD COLUMN IF NOT EXISTS payload_status text NOT NULL DEFAULT 'NotRetrieved';